insert into nodes (node_type, slug, title, summary, status, meta_title, meta_description, legacy_slugs, published_at) values ('article', 'male-airport-velana-international-airport', 'Malé Airport | Velana International Airport', 'Discover all you need to know about Malé Airport, also known as Velana International Airport, the primary gateway to the Maldives. Find information on flights, facilities, and more.', 'published', 'Malé Airport | Velana International Airport | Maldives Travel Guide | MTG', 'Discover all you need to know about Malé Airport, also known as Velana International Airport, the primary gateway to the Maldives. Find information on flights, facilities, and more.', ARRAY['/articles/maldives-international-airport.html']::text[], now()) on conflict (node_type, slug) do nothing;
insert into articles (id, body, reading_time_minutes) select id, '<h2>Introduction</h2><p>Velana International Airport, widely known as Malé Airport, is the main international gateway to the breathtaking islands of the Maldives. Situated on Hulhulé Island, a short distance from the capital city, Malé, this airport is a crucial hub for travelers from around the globe. Offering state-of-the-art facilities, extensive connectivity, and world-class services, Malé Airport plays a vital role in the Maldivian tourism industry, handling millions of passengers annually.</p><p>The Maldives is renowned for its idyllic beaches, crystal-clear waters, and luxurious resorts. Whether you''re arriving for a family vacation, a romantic getaway, or an adventurous solo trip, your journey begins at Velana International Airport. This guide provides an in-depth look at everything you need to know about Malé Airport, including its history, facilities, transportation options, and travel tips.</p><h4>Quick Navigations</h4><p>Airport Overview Flight Informationl Facilities and Services Transportation and Accessibility Travel Tips for Velana International Airport Maldives Airport Map Things to do at the maldives airport List of Maldives Airports Frequently Asked Questions</p><h2>Airport Overview</h2><p>Velana International Airport (IATA: MLE, ICAO: VRMM) is the busiest and most prominent airport in the Maldives, serving as the primary entry point for both international tourists and domestic travelers. The airport''s strategic location on Hulhulé Island, adjacent to the capital city of Malé, makes it an essential hub for air travel in the region.</p><p>Originally known as Hulhulé Airport, it was inaugurated in 1960 and has since undergone several expansions and upgrades to accommodate the growing number of visitors to the Maldives. In 2017, the airport was renamed Velana International Airport in honor of Ibrahim Nasir, the second President of the Maldives, who played a significant role in the nation''s development. Today, Velana International Airport is equipped with modern facilities, including a new runway capable of handling the world''s largest aircraft, such as the Airbus A380.</p>', 2 from nodes where node_type = 'article' and slug = 'male-airport-velana-international-airport' on conflict (id) do nothing;
